;
; XTOT -- docs/bios/TOTEXT.md round 1 (2026-11-17): TOTEXT ($00D2) on the VG-8020 against zerobas. The CASE TABLE at
; the end is GENERATED by probes/bios/spec/xtot_cases.py (--gen), whose docstring documents the setup and the 22-byte
; record; the same module decodes the run.
; Run: python3 -u probes/bios/biosl_run.py probes/bios/spec/xtot.asm --row nodisk
; The capture: CAP+1 = $A5 when finished; records from CAP+2.
;
; CLEAN-ROOM: 100% own code; only published BIOS entries and work-area cells; VRAM through RDVRM / FILVRM.
;
; @cap C000
; @caplen 0212
; @timeout 120

RDVRM   equ     $004A
FILVRM  equ     $0056
INITXT  equ     $006C
INIT32  equ     $006F
INIGRP  equ     $0072
INIMLT  equ     $0075
TOTEXT  equ     $00D2
LINL40  equ     $F3AE
LINL32  equ     $F3AF
LINLEN  equ     $F3B0
CRTCNT  equ     $F3B1
RG0SAV  equ     $F3DF
CSRY    equ     $F3DC
CSRX    equ     $F3DD
CNSDFG  equ     $F3DE
SCRMOD  equ     $FCAF
OLDSCR  equ     $FCB0

DONE    equ     $C000
CAP     equ     $C001
CAPLEN  equ     530
ptr     equ     $EF00
tptr    equ     $EF02
cmode   equ     $EF04
cold    equ     $EF05
ccns    equ     $EF06

                org     $4000
                db      "AB"
                dw      init, 0, 0, 0
                ds      6, 0

init:
                ld      hl, CAP
                ld      de, CAP+1
                ld      bc, CAPLEN - 1
                ld      (hl), 0
                ldir
                ld      hl, CAP+2
                ld      (ptr), hl
                ld      hl, cases
                ld      (tptr), hl
next:
                ld      hl, (tptr)
                ld      a, (hl)
                cp      $FF
                jp      z, finish
                ld      de, cmode
                ld      bc, 3
                ldir
                ld      (tptr), hl
                xor     a
                ld      (CNSDFG), a
                ld      a, 40
                ld      (LINL40), a
                ld      a, 32
                ld      (LINL32), a
                ld      a, 24
                ld      (CRTCNT), a
                ld      a, (cmode)
                or      a
                jr      nz, m_1
                call    INITXT
                jr      m_done
m_1:
                cp      1
                jr      nz, m_2
                call    INIT32
                jr      m_done
m_2:
                cp      2
                jr      nz, m_3
                call    INIGRP
                jr      m_done
m_3:
                call    INIMLT
m_done:
                ld      a, (cold)
                ld      (OLDSCR), a
                ld      a, 37
                ld      (LINL40), a
                ld      a, 29
                ld      (LINL32), a
                ld      a, (ccns)
                ld      (CNSDFG), a
                ld      a, 24
                ld      (CRTCNT), a
                ld      hl, 0
                ld      bc, $4000
                ld      a, $5A
                call    FILVRM
                ld      a, 7
                ld      (CSRX), a
                ld      a, 5
                ld      (CSRY), a
                call    TOTEXT
                ; the record
                ld      hl, RG0SAV
                ld      b, 8
r_rg:
                ld      a, (hl)
                call    emit
                inc     hl
                djnz    r_rg
                ld      a, (SCRMOD)
                call    emit
                ld      a, (OLDSCR)
                call    emit
                ld      a, (LINLEN)
                call    emit
                ld      a, (CRTCNT)
                call    emit
                ld      a, (CSRX)
                call    emit
                ld      a, (CSRY)
                call    emit
                ld      a, (CNSDFG)
                call    emit
                ld      hl, 0
                ld      bc, 960
                call    vsum
                ld      hl, $1800
                ld      bc, 768
                call    vsum
                ld      hl, 0
                ld      bc, $4000
                call    vsum
                ld      a, $C3                  ; the record's sentinel
                call    emit
                jp      next

finish:
                ld      a, $A5
                ld      (CAP+1), a
                ld      (DONE), a
halt_lp:
                jr      halt_lp

; vsum -- emit sum16 (low, high) of BC VRAM bytes from HL
vsum:
                ld      de, 0
vs_lp:
                push    bc
                push    de
                push    hl
                call    RDVRM
                pop     hl
                pop     de
                add     a, e
                ld      e, a
                jr      nc, vs_nc
                inc     d
vs_nc:
                pop     bc
                inc     hl
                dec     bc
                ld      a, b
                or      c
                jr      nz, vs_lp
                ld      a, e
                call    emit
                ld      a, d
                jp      emit

emit:
                push    hl
                ld      hl, (ptr)
                ld      (hl), a
                inc     hl
                ld      (ptr), hl
                pop     hl
                ret

; ---- GENERATED by xtot_cases.py --gen: mode, OLDSCR, CNSDFG; $FF ends ----
cases:
                db      0, $00, 0   ; TOTEXT from SCREEN 0 OLDSCR 0x00 CNSDFG 0
                db      0, $00, 1   ; TOTEXT from SCREEN 0 OLDSCR 0x00 CNSDFG 1
                db      0, $01, 0   ; TOTEXT from SCREEN 0 OLDSCR 0x01 CNSDFG 0
                db      0, $01, 1   ; TOTEXT from SCREEN 0 OLDSCR 0x01 CNSDFG 1
                db      0, $5A, 0   ; TOTEXT from SCREEN 0 OLDSCR 0x5a CNSDFG 0
                db      0, $5A, 1   ; TOTEXT from SCREEN 0 OLDSCR 0x5a CNSDFG 1
                db      1, $00, 0   ; TOTEXT from SCREEN 1 OLDSCR 0x00 CNSDFG 0
                db      1, $00, 1   ; TOTEXT from SCREEN 1 OLDSCR 0x00 CNSDFG 1
                db      1, $01, 0   ; TOTEXT from SCREEN 1 OLDSCR 0x01 CNSDFG 0
                db      1, $01, 1   ; TOTEXT from SCREEN 1 OLDSCR 0x01 CNSDFG 1
                db      1, $5A, 0   ; TOTEXT from SCREEN 1 OLDSCR 0x5a CNSDFG 0
                db      1, $5A, 1   ; TOTEXT from SCREEN 1 OLDSCR 0x5a CNSDFG 1
                db      2, $00, 0   ; TOTEXT from SCREEN 2 OLDSCR 0x00 CNSDFG 0
                db      2, $00, 1   ; TOTEXT from SCREEN 2 OLDSCR 0x00 CNSDFG 1
                db      2, $01, 0   ; TOTEXT from SCREEN 2 OLDSCR 0x01 CNSDFG 0
                db      2, $01, 1   ; TOTEXT from SCREEN 2 OLDSCR 0x01 CNSDFG 1
                db      2, $5A, 0   ; TOTEXT from SCREEN 2 OLDSCR 0x5a CNSDFG 0
                db      2, $5A, 1   ; TOTEXT from SCREEN 2 OLDSCR 0x5a CNSDFG 1
                db      3, $00, 0   ; TOTEXT from SCREEN 3 OLDSCR 0x00 CNSDFG 0
                db      3, $00, 1   ; TOTEXT from SCREEN 3 OLDSCR 0x00 CNSDFG 1
                db      3, $01, 0   ; TOTEXT from SCREEN 3 OLDSCR 0x01 CNSDFG 0
                db      3, $01, 1   ; TOTEXT from SCREEN 3 OLDSCR 0x01 CNSDFG 1
                db      3, $5A, 0   ; TOTEXT from SCREEN 3 OLDSCR 0x5a CNSDFG 0
                db      3, $5A, 1   ; TOTEXT from SCREEN 3 OLDSCR 0x5a CNSDFG 1
                db      $FF
